        // SUPPRESS_CSA_NEXTLINE(alpha.core.AllocatorETSCheckerHint)
        superRef->AsETSTypeReference()->Part()->TypeParams()->Clone(ProgramAllocator(), nullptr);
    superPartialRefTypeParams->SetTsType(nullptr);
